<% url = @question.persisted? ? moderate_quiz_question_path(@quiz, @question) : moderate_quiz_questions_path(@quiz) %>
<% method = @question.persisted? ? :patch : :post %>
<form action="<%= url %>" method="post" id="question-form">
  <input type="hidden" name="_method" value="<%= method %>">
  <input type="hidden" name="authenticity_token" value="<%= form_authenticity_token %>">

  <% if @question.errors.any? %>
    <div class="errors">
      <ul>
        <% @question.errors.full_messages.each do |msg| %>
          <li><%= h msg %></li>
        <% end %>
      </ul>
    </div>
  <% end %>

  <div class="field">
    <label for="question_body">Question</label>
    <textarea id="question_body" name="question[body]" class="input" rows="3" required aria-label="Question" placeholder="Question"><%= h @question.body %></textarea>
  </div>

  <div class="field">
    <span class="field-label">Options</span>
    <span class="field-hint">Mark the correct options, at least one. Empty rows are skipped.</span>
  </div>

  <div class="option-rows" id="option-rows">
    <% @option_rows.each_with_index do |opt, idx| %>
      <% num = idx + 1 %>
      <div class="option-row" data-option-row>
        <div style="display:flex; flex-direction:column; gap:4px;">
          <label for="question_options_attributes_<%= idx %>_text" class="field-label">Option <%= num %></label>
          <input id="question_options_attributes_<%= idx %>_text" name="question[options_attributes][<%= idx %>][text]" type="text" class="input" value="<%= h opt["text"] %>" placeholder="Option <%= num %>" aria-label="Option <%= num %>">
        </div>
        <div>
          <input type="hidden" name="question[options_attributes][<%= idx %>][correct]" value="0">
          <label class="checkbox">
            <input id="question_options_attributes_<%= idx %>_correct" name="question[options_attributes][<%= idx %>][correct]" type="checkbox" value="1" <%= "checked" if opt["correct"] %> aria-label="Option <%= num %> is correct">
            Option <%= num %> is correct
          </label>
        </div>
      </div>
    <% end %>
  </div>
  <div class="buttons" style="margin-bottom: 28px">
    <button type="button" id="add-option" class="btn btn--ghost btn--sm">Add option</button>
  </div>

  <div class="field">
    <input type="hidden" name="question[active]" value="0">
    <label class="checkbox" for="question_active">
      <input id="question_active" name="question[active]" type="checkbox" value="1" <%= "checked" if @question.active %> aria-label="Active">
      Active
    </label>
    <span class="field-hint">Only active questions are played.</span>
  </div>

  <div class="buttons">
    <button type="submit" class="btn btn--pink">Save question</button>
    <a class="btn btn--ghost" href="<%= moderate_quiz_path(@quiz) %>">Cancel</a>
  </div>
</form>

<script>
(function() {
  var btn = document.getElementById('add-option');
  if (!btn) return;
  btn.addEventListener('click', function() {
    var container = document.getElementById('option-rows');
    var count = container.querySelectorAll('[data-option-row]').length;
    var nextIndex = count;
    var nextNum = count + 1;
    var div = document.createElement('div');
    div.className = 'option-row';
    div.setAttribute('data-option-row', '');
    var html = '';
    html += '<div style="display:flex; flex-direction:column; gap:4px;">';
    html += '<label for="question_options_attributes_' + nextIndex + '_text" class="field-label">Option ' + nextNum + '</label>';
    html += '<input id="question_options_attributes_' + nextIndex + '_text" name="question[options_attributes][' + nextIndex + '][text]" type="text" class="input" value="" placeholder="Option ' + nextNum + '" aria-label="Option ' + nextNum + '">';
    html += '</div>';
    html += '<div>';
    html += '<input type="hidden" name="question[options_attributes][' + nextIndex + '][correct]" value="0">';
    html += '<label class="checkbox">';
    html += '<input id="question_options_attributes_' + nextIndex + '_correct" name="question[options_attributes][' + nextIndex + '][correct]" type="checkbox" value="1" aria-label="Option ' + nextNum + ' is correct">';
    html += ' Option ' + nextNum + ' is correct';
    html += '</label>';
    html += '</div>';
    div.innerHTML = html;
    container.appendChild(div);
  });
})();
</script>
"
}

