module Moderate
  class QuizzesController < BaseController
    def index
      @quizzes = Quiz.order(:id)
    end

    def show
      @quiz = Quiz.find(params[:id])
      @questions = @quiz.questions.includes(:options).order(:position, :id)
      # For numbering active questions: map question id -> active index (1-based)
      active = @questions.select(&:active)
      @active_numbers = {}
      active.each_with_index { |q, i| @active_numbers[q.id] = i + 1 }
    end

    def new
      @quiz = Quiz.new
    end

    def create
      @quiz = Quiz.new(quiz_params)
      if @quiz.save
        redirect_to moderate_quiz_path(@quiz)
      else
        render :new, status: :unprocessable_entity
      end
    end

    def edit
      @quiz = Quiz.find(params[:id])
    end

    def update
      @quiz = Quiz.find(params[:id])
      if @quiz.update(quiz_params)
        redirect_to moderate_quiz_path(@quiz)
      else
        render :edit, status: :unprocessable_entity
      end
    end

    def destroy
      @quiz = Quiz.find(params[:id])
      @quiz.destroy
      redirect_to moderate_root_path
    end

    def export
      @quiz = Quiz.find(params[:id])
      @questions = @quiz.questions.includes(:options).order(:position, :id)
      data = {
        "title" => @quiz.title,
        "questions" => @questions.map do |q|
          {
            "text" => q.body,
            "active" => !!q.active,
            "options" => q.options.sort_by { |o| [o.position, o.id] }.map do |opt|
              { "text" => opt.text, "correct" => !!opt.correct }
            end
          }
        end
      }
      @export_json = JSON.pretty_generate(data)
    end

    private

    def quiz_params
      params.require(:quiz).permit(:title)
    end
  end
end
